widget.solution:
import math


def diagnose(losses):
    first = losses[0]
    if any(not math.isfinite(x) for x in losses) or max(losses) > 1.1 * first:
        return 'diverging'
    if all(abs(x - first) < 1e-12 for x in losses):
        return 'stuck'
    if losses[-1] > 0.98 * first:
        return 'slow'
    return 'healthy'

